<?php
/**
 * Prompt composition -- a port of bookends/prompt.py.
 *
 * Two implementations of one contract is a drift risk, so this is pinned by
 * tests/fixtures/prompts.json, generated by the Python code. tests/run.php fails
 * if the two disagree by a single character. If you change a rule here, change it
 * in the Python and regenerate the fixtures with:
 *
 *     python tools/make_prompt_fixtures.py
 */
declare(strict_types=1);

if (!defined('QB_BOOT')) {
    http_response_code(404);
    exit;
}

final class Prompts
{
    /** Must match bookends/prompt.py byte for byte. */
    public const NO_TEXT_CLAUSE = 'No text, lettering, captions, watermarks or speech bubbles anywhere in the picture.';
    public const DEFAULT_STYLE_SUFFIX = "Keep the subject's proportions, colours and design exactly as in the reference images.";
    public const PLATE_LABEL = 'the empty background plate for this set, with nobody in frame';
    public const START_FRAME_LABEL = 'frame 0 of this shot, already approved and rendered';
    public const MAX_WORDS = 120;

    /** Mirrors STYLES in bookends/prompt.py. */
    public const STYLES = [
        'pixar' => '3D Pixar-style animated film look, expressive subsurface-lit materials, soft cinematic depth of field, cinematic key light',
        'clay' => 'stop-motion claymation look, handcrafted plasticine texture with faint fingerprints, miniature set lighting, shallow depth of field',
        'cartoon' => '2D modern cel-shaded cartoon illustration, bold clean linework, flat shading with a rim light',
        'anime' => 'theatrical anime key visual, crisp line art, cel-shaded lighting, rich colour grading',
        'noir' => '1940s black-and-white film noir still, high-contrast chiaroscuro lighting, 35mm film grain',
        'realistic' => 'photorealistic live-action film still, 35mm anamorphic lens, natural skin and material texture, cinematic lighting',
    ];

    public const ROLE_PHRASES = [
        'front' => 'front view',
        'side' => 'side view',
        'back' => 'back view',
        'three_quarter' => 'three-quarter view',
        'detail' => 'detail',
        'plate' => 'empty background plate',
        'other' => 'reference',
    ];

    public static function rolePhrase(string $role): string
    {
        return self::ROLE_PHRASES[$role] ?? self::ROLE_PHRASES['other'];
    }

    /**
     * The noun phrase written into refs.json at export time, and shown in the
     * preview. A description wins; otherwise kind + name + view.
     */
    public static function labelFor(string $kind, string $name, ?string $description, string $role): string
    {
        $desc = trim((string) $description);
        if ($role === 'plate') {
            return $desc !== '' ? $desc : 'the ' . trim($name) . ' background, empty of characters';
        }
        $phrase = self::rolePhrase($role);
        if ($desc !== '') {
            return $desc . ', ' . $phrase;
        }
        return 'the ' . $kind . ' ' . trim($name) . ', ' . $phrase;
    }

    /** "Image 1 shows X. Image 2 shows Y." */
    public static function describe(array $labels): string
    {
        $parts = [];
        foreach (array_values($labels) as $i => $label) {
            $parts[] = 'Image ' . ($i + 1) . ' shows ' . $label . '.';
        }
        return implode(' ', $parts);
    }

    public static function styleSuffix(?string $style): string
    {
        $style = trim((string) $style);
        if ($style === '') {
            return self::DEFAULT_STYLE_SUFFIX;
        }
        $key = strtolower($style);
        $body = self::STYLES[$key] ?? rtrim($style, '.');
        return $body . '. ' . self::DEFAULT_STYLE_SUFFIX;
    }

    /**
     * Compose a prompt exactly as the Python tool does.
     *
     * @param list<string> $labels one per image, in slot order
     * @return array{prompt:string, notes:list<string>}
     */
    public static function compose(string $body, array $labels, ?string $style, int $maxWords = self::MAX_WORDS): array
    {
        $body = trim($body);
        if ($body === '') {
            throw new InvalidArgumentException('shot text is empty');
        }

        $notes = [];
        $words = self::wordCount($body);
        if ($words > $maxWords) {
            $notes[] = "shot text is $words words, over the $maxWords-word budget; the model spreads attention across boilerplate when a prompt is long";
        }
        if (str_contains($body, '"') || str_contains($body, "\u{201c}") || str_contains($body, "\u{201d}")) {
            $notes[] = 'shot text contains quotation marks; if this is dialogue it will be lettered into the frame. Describe what is seen and heard, not what is said.';
        }
        if (self::mentionsNegation($body)) {
            $notes[] = "shot text contains a negation; prefer explaining the absence ('the white hen is inside the coop') over forbidding it ('no hens')";
        }

        $preamble = $labels === [] ? '' : self::describe($labels);
        $parts = array_values(array_filter(
            [$preamble, $body, self::styleSuffix($style), self::NO_TEXT_CLAUSE],
            static fn (string $p): bool => $p !== ''
        ));
        $prompt = implode(' ', $parts);
        if ($labels === []) {
            $notes[] = 'no reference images: this is a text-only generation';
        }
        return ['prompt' => $prompt, 'notes' => $notes];
    }

    /** Python's str.split() semantics: split on runs of whitespace. */
    public static function wordCount(string $s): int
    {
        $parts = preg_split('/\s+/u', trim($s), -1, PREG_SPLIT_NO_EMPTY);
        return $parts === false ? 0 : count($parts);
    }

    /** Matches prompt.py: a literal "no " anywhere, case-insensitively. */
    private static function mentionsNegation(string $body): bool
    {
        return stripos($body, 'no ') !== false;
    }

    /** A short style name for display, or the free text itself. */
    public static function styleLabel(?string $style): string
    {
        $style = trim((string) $style);
        if ($style === '') {
            return '(project default)';
        }
        $key = strtolower($style);
        return isset(self::STYLES[$key]) ? $key : $style;
    }
}
